def sieve_pi(x):
    s = np.ones(x + 1, dtype=bool)
    s[:2] = False
    for q in range(2, isqrt(x) + 1):
        if s[q]:
            s[q * q::q] = False
    return int(s.sum())


def selftest():
    rng = np.random.default_rng(0)
    # 1. compressed DP == sieve
    for n in range(6, 17):
        x = (1 << n) - 1
        _, _, lg = compressed_lucy(x)
        assert lg[-1][0] == sieve_pi(x), n

